    SELECT e.event_id, e.event_name, e.event_date, e.type, e.notes, e.location, e.status, b.category, b.amount, b.event_status
    FROM event AS e
    LEFT JOIN budget AS b ON e.event_id = b.link_to_event
)
SELECT * FROM c_cols;

WITH c_rows AS (
    SELECT event_id, event_name
    FROM c_cols
    WHERE category = 'Parking'
)
SELECT * FROM c_rows;

WITH c_cols AS (
    SELECT t.`GasStationID`, SUM(t.`Amount`) AS TotalRevenue
    FROM transactions_1k AS t
    GROUP BY t.`GasStationID`
)
SELECT * FROM c_cols;

WITH t_join AS (
    SELECT g.`GasStationID`, g.`ChainID`, g.`Country`, g.`Segment`, c.TotalRevenue
    FROM gasstations AS g
    INNER JOIN c_rows c ON g.`GasStationID` = c.GasStationID
)
SELECT * FROM t_join;

WITH final_answer AS (
    SELECT GasStationID, TotalRevenue
    FROM t_join
)
SELECT * FROM final_answer;

WITH c_cols AS (
    SELECT t.`GasStationID`, SUM(t.`Amount`) AS TotalRevenue
    FROM transactions_1k AS t
    GROUP BY t.`GasStationID`
)
SELECT * FROM c_cols;

WITH t_join AS (
    SELECT gs.`GasStationID`, gs.`ChainID`, gs.`Country`, gs.`Segment`, c_cols.TotalRevenue
    FROM gasstations AS gs
    INNER JOIN c_cols ON gs.`GasStationID` = c_cols.`GasStationID`
)
SELECT * FROM t_join;

WITH c_cols AS (
    SELECT t.`GasStationID`, SUM(t.`Amount`) AS total_revenue
    FROM transactions_1k AS t
    GROUP BY t.`GasStationID`
)
SELECT * FROM c_cols;

WITH t_join AS (
    SELECT g.`GasStationID`, g.`ChainID`, g.`Country`, g.`Segment`, c.total_revenue
    FROM gasstations AS g
    INNER JOIN c_rows c ON g.`GasStationID` = c.GasStationID
)
SELECT * FROM t_join;

WITH final_answer AS (
    SELECT GasStationID, total_revenue
    FROM t_join
)
SELECT * FROM final_answer;

WITH c_rows AS (
    SELECT t.`CustomerID`
    FROM c_cols t
    WHERE t.`Date` LIKE '2012-08%' AND t.`Price` / t.`Amount` > 29.00
)
SELECT * FROM c_rows;

WITH final_result AS (
    SELECT `CustomerID`, `Consumption`
    FROM t_join
)
SELECT * FROM final_result;

WITH t_distinct AS (
    SELECT DISTINCT `CustomerID`, `Consumption`
    FROM t_join
)
SELECT * FROM t_distinct;

WITH t_final AS (
    SELECT `CustomerID`, `Consumption`
    FROM t_distinct
)
SELECT * FROM t_final;

WITH final_answer AS (
    SELECT `CustomerID`, `Consumption`
    FROM t_distinct
)
SELECT * FROM final_answer;
